-- ===== session_search.sqlite =====
CREATE TABLE meta (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );
CREATE TABLE session_docs (
                session_id TEXT PRIMARY KEY,
                cwd TEXT NOT NULL,
                updated_at INTEGER NOT NULL,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                content_hash TEXT NOT NULL
            );
CREATE TRIGGER session_docs_ad AFTER DELETE ON session_docs BEGIN
                INSERT INTO session_docs_fts(session_docs_fts, rowid, title, content)
                VALUES ('delete', old.rowid, old.title, old.content);
            END;
CREATE TRIGGER session_docs_ai AFTER INSERT ON session_docs BEGIN
                INSERT INTO session_docs_fts(rowid, title, content)
                VALUES (new.rowid, new.title, new.content);
            END;
CREATE TRIGGER session_docs_au AFTER UPDATE ON session_docs BEGIN
                INSERT INTO session_docs_fts(session_docs_fts, rowid, title, content)
                VALUES ('delete', old.rowid, old.title, old.content);
                INSERT INTO session_docs_fts(rowid, title, content)
                VALUES (new.rowid, new.title, new.content);
            END;
CREATE VIRTUAL TABLE session_docs_fts USING fts5(
                title,
                content,
                content='session_docs',
                content_rowid='rowid'
            );
CREATE TABLE 'session_docs_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE 'session_docs_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE 'session_docs_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE 'session_docs_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;

-- ===== worktrees.db =====
CREATE INDEX idx_worktrees_created ON worktrees(created_at);
CREATE INDEX idx_worktrees_repo ON worktrees(repo_name);
CREATE INDEX idx_worktrees_session ON worktrees(session_id);
CREATE INDEX idx_worktrees_status_kind ON worktrees(status, kind);
CREATE TABLE meta (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
CREATE TABLE worktrees (
    id TEXT PRIMARY KEY,
    path TEXT UNIQUE NOT NULL,
    source_repo TEXT NOT NULL,
    repo_name TEXT NOT NULL,
    kind TEXT NOT NULL DEFAULT 'session',
    creation_mode TEXT NOT NULL DEFAULT 'linked',
    git_ref TEXT,
    head_commit TEXT,
    session_id TEXT,
    creator_pid INTEGER,
    created_at INTEGER NOT NULL,
    last_accessed_at INTEGER,
    status TEXT NOT NULL DEFAULT 'alive',
    metadata TEXT
);
